/** A catch branch. */
export type Catch = {
    /** The optional catch pattern. */
    readonly pattern?: LocalNodeId;
    /** The optional catch pattern type. */
    readonly ty?: LocalNodeId;
    /** The catch body. */
    readonly body: LocalNodeId;
};

export const Catch = {
    /** Encode this value. */
    encode(writer: BinaryWriter, value: Catch): void {
        encodeCatch(writer, value);
    },

    /** Decode one Catch. */
    decode(reader: BinaryReader): Catch {
        return decodeCatch(reader);
    },

    /** Return this value as JSON. */
    toJson(value: Catch): Json {
        return toJsonCatch(value);
    },

    /** Return one Catch from one JSON value. */
    fromJson(value: Json): Catch {
        return fromJsonCatch(value);
    },
};

/** Encode one Catch. */
export function encodeCatch(writer: BinaryWriter, value: Catch): void {
    writer.writeOption(value.pattern, (value0) => {
        encodeLocalNodeId(writer, value0);
    });
    writer.writeOption(value.ty, (value1) => {
        encodeLocalNodeId(writer, value1);
    });
    encodeLocalNodeId(writer, value.body);
}

/** Decode one Catch. */
export function decodeCatch(reader: BinaryReader): Catch {
    const pattern = reader.readOption(() => decodeLocalNodeId(reader));
    const ty = reader.readOption(() => decodeLocalNodeId(reader));
    const body = decodeLocalNodeId(reader);

    return {
        ...(pattern === undefined ? {} : { pattern }),
        ...(ty === undefined ? {} : { ty }),
        body,
    };
}

/** Return one JSON value for one Catch. */
export function toJsonCatch(value: Catch): Json {
    return {
        ...(value.pattern === undefined ? {} : { pattern: toJsonLocalNodeId(value.pattern) }),
        ...(value.ty === undefined ? {} : { ty: toJsonLocalNodeId(value.ty) }),
        body: toJsonLocalNodeId(value.body),
    };
}

/** Return one Catch from one JSON value. */
export function fromJsonCatch(value: Json): Catch {
    const object = jsonObject(value);

    return {
        pattern: jsonOptional(object, "pattern", (value) => fromJsonLocalNodeId(value)),
        ty: jsonOptional(object, "ty", (value) => fromJsonLocalNodeId(value)),
        body: fromJsonLocalNodeId(jsonField(object, "body")),
    };
}

/** A WhereClause is a single clause in a where type declaration. */
export type WhereClause = {
    /** The target type to constrain (like `T` in `T: int32`). */
    readonly left: LocalNodeId;
    /** The constraint type (like `int32` in `T: int32`). */
    readonly right: LocalNodeId;
};

export const WhereClause = {
    /** Encode this value. */
    encode(writer: BinaryWriter, value: WhereClause): void {
        encodeWhereClause(writer, value);
    },

    /** Decode one WhereClause. */
    decode(reader: BinaryReader): WhereClause {
        return decodeWhereClause(reader);
    },

    /** Return this value as JSON. */
    toJson(value: WhereClause): Json {
        return toJsonWhereClause(value);
    },

    /** Return one WhereClause from one JSON value. */
    fromJson(value: Json): WhereClause {
        return fromJsonWhereClause(value);
    },
};

/** Encode one WhereClause. */
export function encodeWhereClause(writer: BinaryWriter, value: WhereClause): void {
    encodeLocalNodeId(writer, value.left);
    encodeLocalNodeId(writer, value.right);
}

/** Decode one WhereClause. */
export function decodeWhereClause(reader: BinaryReader): WhereClause {
    const left = decodeLocalNodeId(reader);
    const right = decodeLocalNodeId(reader);

    return {
        left,
        right,
    };
}

/** Return one JSON value for one WhereClause. */
export function toJsonWhereClause(value: WhereClause): Json {
    return {
        left: toJsonLocalNodeId(value.left),
        right: toJsonLocalNodeId(value.right),
    };
}

/** Return one WhereClause from one JSON value. */
export function fromJsonWhereClause(value: Json): WhereClause {
    const object = jsonObject(value);

    return {
        left: fromJsonLocalNodeId(jsonField(object, "left")),
        right: fromJsonLocalNodeId(jsonField(object, "right")),
    };
}
